SET NOCOUNT ON;
-- Discount history (1 Aug - 31 Oct 2026, Kosovo store) of the products whose approved raise sold at the OLD price after
-- the approval went live (approvals 12, 25, 35 on GjirafaMall KS, 37 on Gjirafa50 KS; lines outside campaign days;
-- product ids from hk.SalesLines x PricingTool.ApprovalItems, listed below). Says which discount held the old price:
-- the calculator's previous push still live, a team deal, or none. Names, amounts and dates only. Read-only.
SELECT CAST('GjirafaMall' AS varchar(20)) AS Db, m.Product_Id AS ProductId, d.Id AS DiscountId,
       CAST(d.Name AS nvarchar(400)) COLLATE DATABASE_DEFAULT AS Name, d.UsePercentage, d.DiscountPercentage, d.DiscountAmount,
       d.StartDateUtc, d.EndDateUtc, CAST(d.DiscountApplyTypeId AS int) AS DiscountApplyTypeId,
       CAST(d.DiscountPlatformTypeId AS int) AS DiscountPlatformTypeId, d.IsVendorDiscount
FROM GjirafaMall.dbo.Discount_AppliedToProducts m WITH (NOLOCK)
JOIN GjirafaMall.dbo.Discount d WITH (NOLOCK) ON d.Id = m.Discount_Id
